---@param self BaseBtTree
local function callFunction(self, name)
    local func = self[name]
    if type(func) ~= "function" then
        LogUtil.logError(string.format("[BtTree] call function failed, function is not exist. function name=%s, treeId=%d", name, self.treeId))
        return 0
    end
    local result = func(self)
    if result == nil then
        result = Define.BtStatus.FAILURE
        LogUtil.logError(string.format("[BtTree] call function failed, result is nil. value name=%s, treeId=%d", name, self.treeId))
    end
    return result
end

---@param self BaseBtTree
local function callValue(self, name)
    local value = self[name]
    if value == nil then
        LogUtil.logError(string.format("[BtTree] call value failed, value is not exist. value name=%s, treeId=%d", name, self.treeId))
        return 0
    end
    return value
end

---@type table<number, function>
local BtTreeProxy = {}
---@class BtTreeDebug
local BtTreeDebug = T(Global, "BtTreeDebug")
BtTreeDebug.curWatchProxy = nil

function BtTreeDebug:onWatchBtTree(treeId)
    local oldProxy = BtTreeDebug.curWatchProxy
    if oldProxy then
        oldProxy.callFunction = oldProxy.callFunctionOld
        oldProxy.callValue = oldProxy.callValueOld
        oldProxy.callFunctionOld = nil
        oldProxy.callValueOld = nil
        BtTreeDebug.curWatchProxy = nil
    end
    local proxy = BtTreeProxy[treeId]
    if not proxy then
        return
    end
    ---@type BaseBtTree
    local self = proxy.btTree()
    ---@type IEntity entity
    local entity = proxy.callValue("entity")
    local entityId = entity and entity.entityId or 0
    proxy.callFunctionOld = proxy.callFunction
    proxy.callFunction = function(name)
        LogUtil.logInfo(string.format("[F1:BtTree] [%s][%s] %s", treeId, entityId, name))
        local result = callFunction(self, name)
        LogUtil.logInfo(string.format("[F2:BtTree] [%s][%s] %s=[%s]", treeId, entityId, name, result))
        return result
    end
    proxy.callValueOld = proxy.callValue
    proxy.callValue = function(name)
        LogUtil.logInfo(string.format("[V1:BtTree] [%s][%s] %s", treeId, entityId, name))
        local result = callValue(self, name)
        LogUtil.logInfo(string.format("[V2:BtTree] [%s][%s] %s=[%s]", treeId, entityId, name, result))
        return result
    end
    BtTreeDebug.curWatchProxy = proxy
end

---@param player SBasePlayer
function BtTreeDebug:tryWatchNearest(player)
    local position = player:getPosition()
    local minDis = 999999999
    local nearest
    for treeId, proxy in pairs(BtTreeProxy) do
        ---@type IEntity entity
        local entity = proxy.callValue("entity")
        if entity and entity.entity then
            local distance = VectorUtil.distance(entity.entity:getPosition(), position)
            if distance < minDis then
                minDis = distance
                nearest = treeId
            end
        end
    end
    if nearest then
        self:onWatchBtTree(nearest)
    end
end

---@class BaseBtTree : EventObservable
BaseBtTree = class("BaseBtTree", EventObservable)

function BaseBtTree:ctor()

end

---初始化行为树
---@param btTreeName string 行为数名称
---@param updateInterval number 行为数执行时间间隔
function BaseBtTree:initBtTree(btTreeName, updateInterval)
    if #btTreeName == 0 then
        return
    end
    updateInterval = updateInterval or 0.5
    self:removeBtTree()
    local proxy = {
        callFunction = function(name)
            return callFunction(self, name)
        end,
        callValue = function(name)
            return callValue(self, name)
        end,
        btTree = function()
            return self
        end
    }
    self.treeId = BtTreeController.Instance():addBtTree(btTreeName, proxy, updateInterval)
    BtTreeProxy[self.treeId] = proxy
end

---删除行为树
function BaseBtTree:removeBtTree()
    if self.treeId and self.treeId ~= 0 then
        BtTreeController.Instance():removeBtTree(self.treeId)
        BtTreeProxy[self.treeId] = nil
    end
end

function BaseBtTree:setBtTreeActive(active)
    if self.treeId and self.treeId ~= 0 then
        BtTreeController.Instance():setBtTreeActive(self.treeId, active)
    end
end

return BaseBtTree